use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl Expr { # [doc = " Check if this expression is potentially a trivial const arg, i.e., one that can _potentially_"] # [doc = " be represented without an anon const in the HIR."] # [doc = ""] # [doc = " This will unwrap at most one block level (curly braces). After that, if the expression"] # [doc = " is a path, it mostly dispatches to [`Path::is_potential_trivial_const_arg`]."] # [doc = " See there for more info about `allow_mgca_arg`."] # [doc = ""] # [doc = " The only additional thing to note is that when `allow_mgca_arg` is false, this function"] # [doc = " will only allow paths with no qself, before dispatching to the `Path` function of"] # [doc = " the same name."] # [doc = ""] # [doc = " Does not ensure that the path resolves to a const param/item, the caller should check this."] # [doc = " This also does not consider macros, so it's only correct after macro-expansion."] pub fn is_potential_trivial_const_arg (& self , allow_mgca_arg : bool) -> bool { let this = self . maybe_unwrap_block () ; if allow_mgca_arg { matches ! (this . kind , ExprKind :: Path (..)) } else { if let ExprKind :: Path (None , path) = & this . kind && path . is_potential_trivial_const_arg (allow_mgca_arg) { true } else { false } } } # [doc = " Returns an expression with (when possible) *one* outer brace removed"] pub fn maybe_unwrap_block (& self) -> & Expr { if let ExprKind :: Block (block , None) = & self . kind && let [stmt] = block . stmts . as_slice () && let StmtKind :: Expr (expr) = & stmt . kind { expr } else { self } } # [doc = " Determines whether this expression is a macro call optionally wrapped in braces . If"] # [doc = " `already_stripped_block` is set then we do not attempt to peel off a layer of braces."] # [doc = ""] # [doc = " Returns the [`NodeId`] of the macro call and whether a layer of braces has been peeled"] # [doc = " either before, or part of, this function."] pub fn optionally_braced_mac_call (& self , already_stripped_block : bool ,) -> Option < (bool , NodeId) > { match & self . kind { ExprKind :: Block (block , None) if let [stmt] = & * block . stmts && ! already_stripped_block => { match & stmt . kind { StmtKind :: MacCall (_) => Some ((true , stmt . id)) , StmtKind :: Expr (expr) if let ExprKind :: MacCall (_) = & expr . kind => { Some ((true , expr . id)) } _ => None , } } ExprKind :: MacCall (_) => Some ((already_stripped_block , self . id)) , _ => None , } } pub fn to_bound (& self) -> Option < GenericBound > { match & self . kind { ExprKind :: Path (None , path) => Some (GenericBound :: Trait (PolyTraitRef :: new (ThinVec :: new () , path . clone () , TraitBoundModifiers :: NONE , self . span , Parens :: No ,))) , _ => None , } } pub fn peel_parens (& self) -> & Expr { let mut expr = self ; while let ExprKind :: Paren (inner) = & expr . kind { expr = inner ; } expr } pub fn peel_parens_and_refs (& self) -> & Expr { let mut expr = self ; while let ExprKind :: Paren (inner) | ExprKind :: AddrOf (BorrowKind :: Ref , _ , inner) = & expr . kind { expr = inner ; } expr } # [doc = " Attempts to reparse as `Ty` (for diagnostic purposes)."] pub fn to_ty (& self) -> Option < Box < Ty > > { let kind = match & self . kind { ExprKind :: Path (qself , path) => TyKind :: Path (qself . clone () , path . clone ()) , ExprKind :: MacCall (mac) => TyKind :: MacCall (mac . clone ()) , ExprKind :: Paren (expr) => expr . to_ty () . map (TyKind :: Paren) ? , ExprKind :: AddrOf (BorrowKind :: Ref , mutbl , expr) => { expr . to_ty () . map (| ty | TyKind :: Ref (None , MutTy { ty , mutbl : * mutbl })) ? } ExprKind :: Repeat (expr , expr_len) => { expr . to_ty () . map (| ty | TyKind :: Array (ty , expr_len . clone ())) ? } ExprKind :: Array (exprs) if let [expr] = exprs . as_slice () => { expr . to_ty () . map (TyKind :: Slice) ? } ExprKind :: Tup (exprs) => { let tys = exprs . iter () . map (| expr | expr . to_ty ()) . collect :: < Option < ThinVec < _ > > > () ? ; TyKind :: Tup (tys) } ExprKind :: Binary (binop , lhs , rhs) if binop . node == BinOpKind :: Add => { if let (Some (lhs) , Some (rhs)) = (lhs . to_bound () , rhs . to_bound ()) { TyKind :: TraitObject (vec ! [lhs , rhs] , TraitObjectSyntax :: None) } else { return None ; } } ExprKind :: Underscore => TyKind :: Infer , _ => return None , } ; Some (Box :: new (Ty { kind , id : self . id , span : self . span , tokens : None })) } pub fn precedence (& self) -> ExprPrecedence { fn prefix_attrs_precedence (attrs : & AttrVec) -> ExprPrecedence { for attr in attrs { if let AttrStyle :: Outer = attr . style { return ExprPrecedence :: Prefix ; } } ExprPrecedence :: Unambiguous } match & self . kind { ExprKind :: Closure (closure) => { match closure . fn_decl . output { FnRetTy :: Default (_) => ExprPrecedence :: Jump , FnRetTy :: Ty (_) => prefix_attrs_precedence (& self . attrs) , } } ExprKind :: Break (_ , value) | ExprKind :: Ret (value) | ExprKind :: Yield (YieldKind :: Prefix (value)) | ExprKind :: Yeet (value) => match value { Some (_) => ExprPrecedence :: Jump , None => prefix_attrs_precedence (& self . attrs) , } , ExprKind :: Become (_) => ExprPrecedence :: Jump , ExprKind :: Range (..) => ExprPrecedence :: Range , ExprKind :: Binary (op , ..) => op . node . precedence () , ExprKind :: Cast (..) => ExprPrecedence :: Cast , ExprKind :: Assign (..) | ExprKind :: AssignOp (..) => ExprPrecedence :: Assign , ExprKind :: AddrOf (..) | ExprKind :: Let (..) | ExprKind :: Unary (..) => ExprPrecedence :: Prefix , ExprKind :: Array (_) | ExprKind :: Await (..) | ExprKind :: Use (..) | ExprKind :: Block (..) | ExprKind :: Call (..) | ExprKind :: ConstBlock (_) | ExprKind :: Continue (..) | ExprKind :: Field (..) | ExprKind :: ForLoop { .. } | ExprKind :: FormatArgs (..) | ExprKind :: Gen (..) | ExprKind :: If (..) | ExprKind :: IncludedBytes (..) | ExprKind :: Index (..) | ExprKind :: InlineAsm (..) | ExprKind :: Lit (_) | ExprKind :: Loop (..) | ExprKind :: MacCall (..) | ExprKind :: Match (..) | ExprKind :: MethodCall (..) | ExprKind :: OffsetOf (..) | ExprKind :: Paren (..) | ExprKind :: Path (..) | ExprKind :: Repeat (..) | ExprKind :: Struct (..) | ExprKind :: Try (..) | ExprKind :: TryBlock (..) | ExprKind :: Tup (_) | ExprKind :: Type (..) | ExprKind :: Underscore | ExprKind :: UnsafeBinderCast (..) | ExprKind :: While (..) | ExprKind :: Yield (YieldKind :: Postfix (..)) | ExprKind :: Err (_) | ExprKind :: Dummy => prefix_attrs_precedence (& self . attrs) , } } # [doc = " To a first-order approximation, is this a pattern?"] pub fn is_approximately_pattern (& self) -> bool { matches ! (& self . peel_parens () . kind , ExprKind :: Array (_) | ExprKind :: Call (_ , _) | ExprKind :: Tup (_) | ExprKind :: Lit (_) | ExprKind :: Range (_ , _ , _) | ExprKind :: Underscore | ExprKind :: Path (_ , _) | ExprKind :: Struct (_)) } # [doc = " Creates a dummy `Expr`."] # [doc = ""] # [doc = " Should only be used when it will be replaced afterwards or as a return value when an error was encountered."] pub fn dummy () -> Expr { Expr { id : DUMMY_NODE_ID , kind : ExprKind :: Dummy , span : DUMMY_SP , attrs : ThinVec :: new () , tokens : None , } } }
}